user_roles:
CREATE TABLE user_roles (
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role    VARCHAR(50) NOT NULL,
    PRIMARY KEY (user_id, role)
);

refresh_tokens:
CREATE TABLE refresh_tokens (
    id          UUID PRIMARY KEY,
    user_id     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash  VARCHAR(255) NOT NULL UNIQUE,
    expires_at  TIMESTAMPTZ NOT NULL,
    revoked     BOOLEAN NOT NULL DEFAULT FALSE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_refresh_tokens_user ON refresh_tokens(user_id);

CREATE INDEX idx_refresh_tokens_expires ON refresh_tokens(expires_at);

loyalty_transactions:
CREATE TABLE loyalty_transactions (
    id                  UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    loyalty_account_id  UUID NOT NULL REFERENCES loyalty_accounts(id),
    order_id            UUID,
    type                VARCHAR(20) NOT NULL,
    points              INTEGER NOT NULL,
    description         VARCHAR(500),
    occurred_at         TIMESTAMPTZ NOT NULL
);

CREATE INDEX idx_loyalty_tx_account  ON loyalty_transactions(loyalty_account_id);

CREATE INDEX idx_loyalty_tx_occurred ON loyalty_transactions(occurred_at);

order_items:
CREATE TABLE order_items (
    id            UUID PRIMARY KEY,
    order_id      UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
    product_id    UUID NOT NULL,
    product_name  VARCHAR(200) NOT NULL,
    quantity      DECIMAL(10,2) NOT NULL,
    unit_price    DECIMAL(10,2) NOT NULL,
    line_total    DECIMAL(10,2) NOT NULL
);

CREATE INDEX idx_order_items_order ON order_items(order_id);

ALTER TABLE order_items ALTER COLUMN product_name DROP NOT NULL;

stock_balances:
CREATE TABLE stock_balances (
    id                UUID PRIMARY KEY,
    product_id        UUID NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
    store_id          UUID NOT NULL REFERENCES stores(id),
    quantity_in_stock NUMERIC(12,3) NOT NULL DEFAULT 0,
    average_cost      NUMERIC(10,2) NOT NULL DEFAULT 0,
    CONSTRAINT stock_balances_product_store_unique UNIQUE (product_id, store_id)
);

CREATE INDEX idx_stock_balances_product_id ON stock_balances(product_id);

CREATE INDEX idx_stock_balances_store_id ON stock_balances(store_id);

stock_batches:
CREATE TABLE stock_batches (
    id                 UUID PRIMARY KEY,
    product_id         UUID NOT NULL REFERENCES products(id),
    store_id           UUID NOT NULL REFERENCES stores(id),
    quantity_received  DECIMAL(10,2) NOT NULL,
    quantity_remaining DECIMAL(10,2) NOT NULL,
    unit_cost          DECIMAL(10,2) NOT NULL,
    received_at        TIMESTAMPTZ NOT NULL,
    expires_at         TIMESTAMPTZ,
    status             VARCHAR(20) NOT NULL,
    source_document_id VARCHAR(100) NOT NULL
);

CREATE INDEX idx_batches_product_received ON stock_batches(product_id, received_at);

CREATE INDEX idx_batches_store ON stock_batches(store_id);

ALTER TABLE stock_batches ADD COLUMN IF NOT EXISTS supplier_id UUID;

stock_transactions:
CREATE TABLE stock_transactions (
    id                 UUID PRIMARY KEY,
    product_id         UUID NOT NULL REFERENCES products(id),
    store_id           UUID NOT NULL REFERENCES stores(id),
    type               VARCHAR(30) NOT NULL,
    quantity           NUMERIC(12,3) NOT NULL,
    cost_basis         NUMERIC(10,2) NOT NULL,
    total_value        NUMERIC(14,2) NOT NULL,
    write_off_reason   VARCHAR(30),
    comment            TEXT,
    source_document_id VARCHAR(255) NOT NULL UNIQUE,
    performer_id       UUID NOT NULL,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_st_product_id ON stock_transactions(product_id);

CREATE INDEX idx_st_store_product ON stock_transactions(store_id, product_id);

CREATE INDEX idx_st_source_doc ON stock_transactions(source_document_id);

ALTER TABLE stock_transactions ALTER COLUMN performer_id DROP NOT NULL;

ALTER TABLE stock_transactions DROP CONSTRAINT IF EXISTS idx_st_source_doc;

ALTER TABLE stock_transactions DROP CONSTRAINT IF EXISTS stock_transactions_source_document_id_key;

purchase_invoices:
CREATE TABLE purchase_invoices (
    id                  UUID PRIMARY KEY,
    invoice_number      VARCHAR(100) NOT NULL,
    supplier_id         UUID NOT NULL REFERENCES suppliers(id),
    supplier_name       VARCHAR(255) NOT NULL,
    store_id            UUID NOT NULL REFERENCES stores(id),
    status              VARCHAR(50) NOT NULL,
    total_amount        NUMERIC(19,2) NOT NULL,
    planned_delivery_at TIMESTAMPTZ,
    received_at         TIMESTAMPTZ,
    comment             TEXT,
    created_by          UUID NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL
);

CREATE UNIQUE INDEX idx_purchase_invoices_supplier_number ON purchase_invoices(supplier_id, invoice_number);

CREATE INDEX idx_purchase_invoices_status ON purchase_invoices(status);

CREATE INDEX idx_purchase_invoices_created_at ON purchase_invoices(created_at DESC);

CREATE INDEX idx_pi_store ON purchase_invoices(store_id);

financial_transactions:
CREATE TABLE financial_transactions (
    id           UUID PRIMARY KEY,
    type         VARCHAR(30) NOT NULL,
    amount       DECIMAL(19,2) NOT NULL,
    reference_id UUID NOT NULL,
    description  TEXT,
    performed_by UUID,
    occurred_at  TIMESTAMPTZ NOT NULL
);

CREATE INDEX idx_finance_occurred_at ON financial_transactions(occurred_at);

CREATE INDEX idx_finance_type ON financial_transactions(type);

CREATE INDEX idx_finance_ref_type ON financial_transactions(reference_id, type);

media_files:
CREATE TABLE media_files (
    id                UUID PRIMARY KEY,
    original_filename VARCHAR(500) NOT NULL,
    mime_type         VARCHAR(100) NOT NULL,
    bucket            VARCHAR(100) NOT NULL,
    base_path         VARCHAR(500) NOT NULL,
    status            VARCHAR(50) NOT NULL,
    uploaded_by       UUID NOT NULL,
    uploaded_at       TIMESTAMPTZ NOT NULL
);

CREATE INDEX idx_media_files_status ON media_files(status);

CREATE INDEX idx_media_files_uploaded_by ON media_files(uploaded_by);

notification_templates:
CREATE TABLE notification_templates (
    id            UUID PRIMARY KEY,
    code          VARCHAR(200) NOT NULL,
    channel       VARCHAR(30) NOT NULL,
    subject       VARCHAR(500),
    body_template TEXT NOT NULL,
    is_active     BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT uk_notification_templates_code_channel UNIQUE (code, channel)
);

CREATE INDEX idx_notification_templates_code ON notification_templates(code);

CREATE INDEX idx_notification_templates_channel ON notification_templates(channel);

CREATE INDEX idx_notification_templates_active ON notification_templates(is_active);

notification_logs:
CREATE TABLE notification_logs (
    id                UUID PRIMARY KEY,
    recipient_id      UUID NOT NULL,
    recipient_contact VARCHAR(500) NOT NULL,
    channel           VARCHAR(30) NOT NULL,
    template_code     VARCHAR(200) NOT NULL,
    status            VARCHAR(30) NOT NULL,
    sent_at           TIMESTAMPTZ,
    error_message     TEXT
);

CREATE INDEX idx_notification_logs_recipient_id ON notification_logs(recipient_id);

CREATE INDEX idx_notification_logs_template_code ON notification_logs(template_code);

CREATE INDEX idx_notification_logs_status ON notification_logs(status);

CREATE INDEX idx_notification_logs_sent_at ON notification_logs(sent_at DESC);

recipes:
CREATE TABLE recipes (
    id          UUID PRIMARY KEY,
    product_id  UUID NOT NULL UNIQUE, -- One recipe per product (e.g. bouquet)
    is_active   BOOLEAN NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ NOT NULL,
    updated_at  TIMESTAMPTZ NOT NULL
);

CREATE INDEX idx_recipes_product_id ON recipes(product_id);

recipe_items:
CREATE TABLE recipe_items (
    id             UUID PRIMARY KEY,
    recipe_id      UUID NOT NULL REFERENCES recipes(id) ON DELETE CASCADE,
    ingredient_id  UUID NOT NULL, -- Reference to another product (e.g. "Red Rose" as ingredient)
    quantity       DECIMAL(19,3) NOT NULL,
    created_at     TIMESTAMPTZ NOT NULL
);

CREATE INDEX idx_recipe_items_recipe_id ON recipe_items(recipe_id);

payments:
CREATE TABLE payments (
    id UUID PRIMARY KEY,
    external_id VARCHAR(255),
    order_id UUID NOT NULL,
    amount DECIMAL(10, 2) NOT NULL,
    status VARCHAR(50) NOT NULL,
    confirmation_url TEXT,
    qr_code_data TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_payments_order_id ON payments(order_id);

CREATE INDEX idx_payments_external_id ON payments(external_id);
